$$
\begin{aligned}
\text{APB ವೃತ್ತಖಂಡದ ವಿಸ್ತೀರ್ಣ} &= \text{OAPB ತ್ರಿಜ್ಯಾಂತರ ಖಂಡದ ವಿಸ್ತೀರ್ಣ} - \Delta \text{OAB ಯ ವಿಸ್ತೀರ್ಣ} \\
&= \frac{\theta}{360} \times \pi r^2 - \Delta \text{OAB ಯ} \\
\text{ವಿಸ್ತೀರ್ಣ.}
\end{aligned}
$$

$$
\begin{pmatrix}
ಹೊಸ ಘನದ \\
ಒಟ್ಟು ಮೇಲ್ಮೈ \\
ವಿಸ್ತೀರ್ಣ
\end{pmatrix}
=
\begin{pmatrix}
ಮೊದಲ \\
ಅರ್ಧಗೋಳದ ಪಾರ್ಶ್ವ \\
ಮೇಲ್ಮೈ ವಿಸ್ತೀರ್ಣ
\end{pmatrix}
+
\begin{pmatrix}
ಸಿಲಿಂಡರಿನ ಪಾರ್ಶ್ವ \\
ಮೇಲ್ಮೈ ವಿಸ್ತೀರ್ಣ
\end{pmatrix}
+
\begin{pmatrix}
ಎರಡನೆಯ \\
ಅರ್ಧಗೋಳದ ಪಾರ್ಶ್ವ \\
ಮೇಲ್ಮೈ ವಿಸ್ತೀರ್ಣ
\end{pmatrix}
$$

$$
\begin{aligned}
\mathrm{P} \ (\text{ಬಾಲಕ}) &= 1 - (\text{ಬಾಲಕ ನಲ್ಲದ}) \\
&= 1 - \mathrm{P} \ (\text{ಬಾಲಕಿ}) \\
&= 1 - \frac{5}{8} = \frac{3}{8}
\end{aligned}
$$
